#include <stdio.h>
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#include <libubox/md5.h>
#include <libubox/utils.h>


#define KiB(n) ((n) * 1024)
#define MiB(n) ((n) * 1024 * 1024)
#define GiB(n) ((n) * 1024 * 1024 * 1024)

typedef bool (*check_t) (const char *path, const char *content, void *priv);
#define BUF_LEN_256 256

typedef bool (*check_t) (const char *path, const char *content, void *priv);



int func (const char *data, check_t check, void *priv) {
	int fd, ret;
	size_t len;
	char *buf;
	char temp[] = "/tmp/cfmanager_XXXXXX";
	char content[BUF_LEN_256 + 1] = { 0 };
	const char *p, *base64;

	base64 = data;
	if (!base64 || (0 != strncmp(base64, "data:", 5)))
		return -1;

	base64 += 5;
	if (!(p = strchr(base64, ';')) || (BUF_LEN_256 < (len = (p - base64))))
		return -1;

	strncpy(content, base64, len);
	if (!(base64 = strstr(data, "base64,")))
		return -1;

	base64 += 7;
	if (MiB(1) < (len = B64_DECODE_LEN(strlen(base64))))
		return -2;

	if((fd = mkstemp(temp)) < 0) {
		return -3;
	}
	if (!(buf = malloc(len + 1))) {
		return -3;
	}
	if ((ret = b64_decode(base64, buf, len)) < 0) {
		free(buf);
		close(fd);
		return -3;
	}
	write(fd, buf, len);
	free(buf);
	close(fd);

	if (!check || check(temp, content, priv))
		unlink(temp);

	return len;
}


#define DATA0 "data:application/octet-stream;base64,"
#define DATA1 "data:application/octet-stream;base64,"
// ca
#define DATA2 "data:application/x-x509-ca-cert;base64,"
#define DATA3 "data:application/x-x509-ca-cert;base64,"


bool check(const char *path, const char *content, void *priv) {
	printf("%s %s\n", path, content);
	return true;
}



int main (int argc, char *argv[]) {
	func(DATA3, check, NULL);



	return 0;
}
